<?php namespace App\Http\Requests; use Illuminate\Foundation\Http\FormRequest; class StoreEventRequest extends FormRequest {public function authorize():bool{return $this->user()?->role?->value==='organizer';}public function rules():array{return ['venue_id'=>['required','exists:venues,id'],'title'=>['required','string','max:180'],'description'=>['nullable','string'],'city'=>['required','string','max:100'],'category'=>['required','string','max:80'],'starts_at'=>['required','date','after:now'],'status'=>['sometimes','in:draft,published'],'max_per_order'=>['sometimes','integer','min:1','max:20'],'ticket_categories'=>['required','array','min:1'],'ticket_categories.*.name'=>['required','string'],'ticket_categories.*.type'=>['required','in:standard,vip,early_bird'],'ticket_categories.*.price'=>['required','numeric','min:0'],'ticket_categories.*.quantity'=>['required','integer','min:1']];}public function messages():array{return ['title.required'=>'اسم الفعالية مطلوب.','venue_id.required'=>'المكان مطلوب.','starts_at.after'=>'تاريخ الفعالية يجب أن يكون في المستقبل.'];}}
